import { test } from "node:test";
import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import { parse } from "yaml";

type Agent = { name: string; status: string; keys?: unknown; github?: unknown; unattended?: boolean };

const agents = parse(await readFile("inventory/agents.yaml", "utf8")) as Agent[];
const limits = parse(await readFile("settings/spend-limits.yaml", "utf8"));
const models = JSON.parse(await readFile("settings/managed-settings.d/10-models.json", "utf8"));

test("every planned agent names keys, github and unattended", () => {
  for (const a of agents.filter((a) => a.status.startsWith("planned"))) {
    assert.ok("keys" in a && "github" in a && "unattended" in a, `${a.name} is missing a field`);
  }
});

test("limits start in shadow and hold new runs above 90 percent", () => {
  assert.equal(limits.mode, "shadow");
  for (const name of Object.keys(limits.agents)) {
    assert.equal(limits.agents[name].hold_new_runs_above_pct, 90);
  }
});

test("Fable is denied", () => assert.deepEqual(models.deniedModels, ["fable"]));
